; [GameState] Handles special game events and cutscenes.
HandleSpecialEvents:
        PHB
        PHP
        PHD
        SEP #$30
        LDA.W $00D0
        LSR A
        TAX
        LDA.L $85807A,X
        PHA
        PLB
        REP #$20
        LDA.W #$0000
        TCD
        LDA.W $0560
        LDX.W $0600
        BNE setGameStateValues
        LDA.W #$0000
; [GameState] Sets $1CD9 and $1CDB state values, processes state logic. Entry: A=value, 16-bit A/X/Y.
setGameStateValues:
        STA.W $1CD9
        LDA.W $0562
        LDX.W $0700
        BNE storeStateValue1CDB
        LDA.W #$0000
; [GameState] Stores value in $1CDB state variable. Entry: A=value, 16-bit A/X/Y.
storeStateValue1CDB:
        STA.W $1CDB
        LDA.W $1C56
        BMI handleNegativeState
        LDA.W $1C56
        BNE checkStateFlags
        JSR.W calculateStateFromEntities
; [GameState] Checks $1CD9/$1CDB flags, clears $1C46 if conditions met. Entry: 16-bit A/X/Y.
checkStateFlags:
        LDA.W $1CD9
        ORA.W $1CDB
        AND.W #$8000
        BEQ updateStateMachine
        LDA.W $1CAC
        AND.W #$00FF
        BEQ updateStateMachine
        STZ.W $1C46
; [StateMachine] Updates state machine based on $1C46 value. Entry: 16-bit A/X/Y.
updateStateMachine:
        LDA.W $1C46
        BNE setStateAndCall
        LDA.W #$0001
        STA.W $1C56
        JSR.W resetGameFlags
; [GameState] Sets $1C56=1 and calls subroutine at $80FE. Entry: 16-bit A/X/Y.
setStateAndCall:
        REP #$20
        DEC.W $1C46
; [GameState] Handles case when $1C56 is negative. Entry: 16-bit A/X/Y.
handleNegativeState:
        REP #$30
        LDX.W #$1540
        LDY.W #$2000
        LDA.W #$00FF
        MVN $7E,$00
        PLD
        PLP
        PLB
        RTL
        db $85
        db $85
        db $85,$85,$85,$87
        db $87,$87
        db $85
        db $85
        db $85
        db $85
        db $85,$85,$7E,$00,$0C,$0E
        db $10
        db $12
        db $14,$00,$00
        db $0C,$02,$16
        db $18
        db $1A
        db $1C,$00,$00
        db $0E
        db $16
        db $04
        db $1E,$20,$22,$00,$00,$10,$18
        db $1E
        db $06,$24,$26,$00,$00
        db $12,$1A
        db $20,$24,$08,$28,$00,$00,$14,$1C,$22,$26,$28,$0A,$00,$00
; [GameState] Calculates state value in $1C83 based on $0600/$0700 entity states and $0627/$0727 values. Entry: 8-bit A, 16-bit X/Y.
calculateStateFromEntities:
        PHP
        SEP #$30
        LDA.W $0600
        BEQ calculateStateFrom0700
        LDA.W $0627
        LSR A
        STA.W $1C83
; [GameState] Calculates state from $0700 entity. Entry: 8-bit A, 16-bit X/Y.
calculateStateFrom0700:
        LDA.W $0700
        BEQ calculateStateFromBothEntities
        LDA.W $0727
        LSR A
        STA.W $1C83
; [GameState] Calculates combined state from both $0600 and $0700 entities. Entry: 8-bit A, 16-bit X/Y.
calculateStateFromBothEntities:
        LDA.W $0600
        AND.W $0700
        BEQ checkConditionAndClearState
        LDA.W $0627
        ASL A
        STA.B $00
        LDA.W $0727
        LSR A
        LSR A
        CLC
        ADC.B $00
        TAX
        LDA.L $858089,X
        STA.W $1C83
; [GameState] Checks $00C8 condition and clears $1C83 if not equal to 4. Entry: 8-bit A, 16-bit X/Y.
checkConditionAndClearState:
        LDA.W $00C8
        CMP.B #$04
        BEQ returnFromStateCalculation
        STZ.W $1C83
; [Helper] Returns from state calculation routine. Entry: 8-bit A, 16-bit X/Y.
returnFromStateCalculation:
        PLP
        RTS
; [GameState] Resets various game flags and state variables. Entry: 16-bit A/X/Y.
resetGameFlags:
        REP #$30
        STZ.W $1C81
        LDA.W $1CD9
        ORA.W $1CDB
        AND.W #$1000
        BEQ checkD0Condition
        LDA.W $1CAC
        AND.W #$00FF
        BEQ checkD0Condition
        LDA.W #$FFFF
        STA.W $1C56
        STZ.W $1C75
        STZ.W $1478
        LDA.W #$0001
        STA.W $1C46
        STZ.W $1CAC
        STZ.W $1478
        JMP.W updateEntityScore
; [GameState] Checks $00D0 condition and branches. Entry: 16-bit A/X/Y.
checkD0Condition:
        LDA.W $00D0
        AND.W #$00FF
        TAX
        LDA.L $858215,X
        STA.B $00
        LDY.W $1C48
        LDA.B ($00),Y
        STA.B $00
        LDA.W $1C83
        AND.W #$00FF
        TAY
        LDA.B ($00),Y
        STA.B $00
        SEP #$30
        LDY.W $1C75
        LDA.B ($00),Y
        CMP.B #$FF
        BNE processEntityState
        REP #$30
        LDA.W #$FFFF
        STA.W $1C56
        STZ.W $1C75
        STZ.W $1478
        LDA.W #$0001
        STA.W $1C46
        STZ.W $1CAC
        LDX.W #$0000
        LDA.L $858313,X
        STA.W $0358
        LDA.L $858315,X
        STA.W $035A
        LDA.L $858317,X
        STA.W $035C
        LDA.L $858319,X
        STA.W $035E
        STZ.W $1478
        JMP.W updateEntityScore
; [Entity] Processes entity state based on various conditions. Entry: 8-bit A, 16-bit X/Y.
processEntityState:
        TAY
        REP #$20
        LDA.W $00D0
        AND.W #$00FF
        TAX
        LDA.L $858233,X
        STA.B $00
        LDA.B ($00),Y
        STA.B $00
        REP #$10
        LDY.W $1C4A
        INC.W $1C4A
        LDA.B ($00),Y
        AND.W #$00FF
        STA.W $1C4E
        CMP.W #$00FD
        BNE handleEntityUpdate
        JMP.W processEntitySound
; [Entity] Handles entity update logic. Entry: 16-bit A/X/Y.
handleEntityUpdate:
        CMP.W #$00FE
        BNE updateEntityPosition
        JMP.W updateEntityHealth
; [Entity] Updates entity position values. Entry: 16-bit A/X/Y.
updateEntityPosition:
        CMP.W #$00FF
        BNE checkEntityBounds
        JMP.W applyEntityDamage
; [Entity] Checks entity bounds and conditions. Entry: 16-bit A/X/Y.
checkEntityBounds:
        CMP.W #$00FB
        BNE dispatchEntityCommand
        JMP.W clearEntityFlags
; [Entity] Dispatches entity commands based on comparison value in A. Handles commands $F7-$FC for physics, velocity, animation, timers. Entry: 16-bit A/X/Y.
dispatchEntityCommand:
        CMP.W #$00F8
        BNE updateEntityVelocity
        JMP.W updateEntityAnimation
; [Physics] Updates entity velocity values. Entry: 16-bit A/X/Y.
updateEntityVelocity:
        CMP.W #$00F9
        BNE applyEntityPhysics
        JMP.W updateEntityRender
; [Physics] Applies physics to entity movement. Entry: 16-bit A/X/Y.
applyEntityPhysics:
        CMP.W #$00F7
        BNE checkEntityAnimation
        JMP.W setEntityActive
; [Animation] Checks and updates entity animation state. Entry: 16-bit A/X/Y.
checkEntityAnimation:
        CMP.W #$00FA
        BNE updateEntityTimer
        INC.W $1C81
        INY
        INC.W $1C4A
        LDA.B ($00),Y
        AND.W #$00FF
        STA.W $1C4E
        JSR.W cleanupEntity
        BRA handleEntityAI
; [Timer] Updates entity timer values. Entry: 16-bit A/X/Y.
updateEntityTimer:
        CMP.W #$00FC
        BEQ handleEntityState
        JSR.W cleanupEntity
; [AI] Handles entity AI decision making. Entry: 16-bit A/X/Y.
handleEntityAI:
        RTS
        db $30,$84
        db $6B,$8E
        db $E5,$92,$96,$9E,$8B,$A5,$5F,$86
        db $13,$8A,$39,$8E
