        db $B7,$C7
        db $73,$D0,$70,$E1,$00,$C7
; [Entity] Handles entity state transitions. Entry: 16-bit A/X/Y.
handleEntityState:
        INY
        INC.W $1C4A
        LDA.B ($00),Y
        AND.W #$00FF
        ASL A
        TAX
        JSR.W ($8262,X)
        JMP.W resetGameFlags
        db $68,$82,$7F,$82,$8C,$82
; [StateMachine] Updates entity state machine. Entry: 16-bit A/X/Y.
updateEntityStateMachine:
        INY
        INC.W $1C4A
        LDA.B ($00),Y
        AND.W #$00FF
        STA.W $1288
        LDA.W #$0080
        STA.W $128A
        JSL.L CalculateAudioVolume
        RTS
; [Entity] Handles entity spawning logic. Entry: 16-bit A/X/Y.
handleEntitySpawn:
