        LDA.B ($00),Y
        AND.W #$00FF
        STA.W $1C44
        RTS
; [Entity] Initializes entity data structures. Entry: 16-bit A/X/Y.
initEntityData:
        INY
        INC.W $1C4A
        INC.W $1C4A
        LDA.B ($00),Y
        STA.W $147A
