; [GameState] Processes game mode based on $00C9 value. Calls various subroutines for different modes. Entry: 8-bit A, 16-bit X/Y.
processGameMode:
        PHB
        PHP
        PHK
        PLB
        REP #$20
        INC.W $1E02
        SEP #$20
        LDA.B #$00
        XBA
        REP #$10
        JSL.L handleMenuTransition
        LDA.W $00C9
        CMP.B #$02
        BCC checkTimerAndProcess
        CMP.B #$04
        BCC jumpToMode4
        CMP.B #$08
        BCS callMode6Handler
        CMP.B #$06
        BCC handleMode2
        BNE checkTimerAndProcess
        JSR.W processEnemyAI
        JSR.W initLevelMusic
        LDA.B #$03
        STA.W $0081
        LDA.B #$48
        STA.W $0084
        LDA.B #$50
        STA.W $0085
        LDA.B #$04
        STA.W $0089
        JMP.W checkTimerAndProcess
; [GameState] Handles game mode 2 logic. Entry: 8-bit A, 16-bit X/Y.
handleMode2:
        JSR.W clearStateFlags
        SEP #$20
        LDA.B #$00
        XBA
        JMP.W checkTimerAndProcess
; [GameState] Jumps to mode 4 handler. Entry: 8-bit A, 16-bit X/Y.
jumpToMode4:
        JMP.W handleMode4Logic
; [GameState] Calls mode 6 handler subroutine. Entry: 8-bit A, 16-bit X/Y.
callMode6Handler:
        JSR.W handleEnemyAttack
; [Timer] Checks $1E95 timer and processes if zero. Entry: 8-bit A, 16-bit X/Y.
checkTimerAndProcess:
        LDA.W $1E95
        BEQ loadDataFromTable
        DEC.W $1E95
        JMP.W storeDataResult
; [Memory] Loads data from table at $DF:AB22 indexed by $1E96. Entry: 8-bit A, 16-bit X/Y.
loadDataFromTable:
        LDX.W $1E96
        PHB
        LDA.B #$DF
        PHA
        PLB
        REP #$20
        LDA.W $AB22,X
        PLB
        STA.B $00
        LDY.W $1E99
        SEP #$20
        LDA.B #$00
        XBA
        PHB
        LDA.B #$DF
        PHA
        PLB
        LDA.B ($00),Y
        PLB
        INY
        STA.W $1E95
; [Memory] Processes data loaded from table. Entry: 8-bit A, 16-bit X/Y.
processLoadedData:
        PHB
        LDA.B #$DF
        PHA
        PLB
        REP #$20
        LDA.B ($00),Y
        PLB
        INY
        INY
        CMP.W #$FFFF
        BEQ updateDataPointer
        TAX
        SEP #$20
        LDA.B #$00
        XBA
        PHB
        LDA.B #$DF
        PHA
        PLB
        LDA.B ($00),Y
        PLB
        INY
        STA.B $00,X
        JMP.W processLoadedData
; [Memory] Updates data pointer values. Entry: 16-bit A/X/Y.
updateDataPointer:
        REP #$20
        STY.W $1E99
        SEP #$20
        LDA.B #$00
        XBA
        PHB
        LDA.B #$DF
        PHA
        PLB
        LDA.B ($00),Y
        PLB
        CMP.B #$FF
        BEQ checkDataCondition
        JMP.W checkTimerAndProcess
; [Memory] Checks data condition and branches. Entry: 8-bit A, 16-bit X/Y.
checkDataCondition:
        REP #$20
        STZ.W $1E99
        INC.W $1E96
        INC.W $1E96
        SEP #$20
        LDA.B #$00
        XBA
        JMP.W checkTimerAndProcess
; [Memory] Stores data processing result. Entry: 8-bit A, 16-bit X/Y.
storeDataResult:
        LDA.W $00D4
        ORA.W $00D5
        BNE decrementTimer
        LDA.W $1E94
        CMP.B #$24
        BCS decrementTimer
        LDA.W $056D
        BIT.B #$10
        BEQ incrementCounter
        LDA.B #$02
        STA.W $00CA
        STZ.W $00CB
        JSL.L InitAudioController
        REP #$20
        LDA.W #$0011
        STA.W $1270
        JSL.L ClearMemoryBlock
        LDA.W #$0001
        STA.W $2142
        JMP.W resetTimerValue
; [Timer] Increments counter value. Entry: 8-bit A, 16-bit X/Y.
incrementCounter:
        SEP #$20
        LDA.W $0561
        BIT.B #$20
        BEQ decrementTimer
; [Timer] Decrements timer value. Entry: 8-bit A, 16-bit X/Y.
decrementTimer:
        SEP #$20
        LDA.B #$00
        XBA
        LDA.W $12C0
        BEQ checkTimerZero
        JSL.L AudioDispatcher
        JSL.L ClearMemoryBlock
        SEP #$20
        LDA.B #$00
        XBA
        STZ.W $12C0
; [Timer] Checks if timer reached zero. Entry: 8-bit A, 16-bit X/Y.
checkTimerZero:
        LDA.W $1288
        BEQ resetTimerValue
        JSL.L SetupDataProcessing80
        SEP #$20
        LDA.B #$00
        XBA
        STZ.W $1288
; [Timer] Resets timer to initial value. Entry: 8-bit A, 16-bit X/Y.
resetTimerValue:
        PLP
        PLB
        RTL
; [GameState] Handles game mode 4 specific logic. Entry: 8-bit A, 16-bit X/Y.
handleMode4Logic:
        SEP #$20
        LDA.B #$00
        XBA
        LDA.W $00C9
        CMP.B #$03
        BEQ processModeTransition
        JSR.W initLevelMusic
; [GameState] Processes transition between game modes. Entry: 8-bit A, 16-bit X/Y.
processModeTransition:
        JSL.L updateGameState
        PLP
        PLB
        RTL
; [GameState] Updates overall game state variables. Entry: 8-bit A, 16-bit X/Y.
updateGameState:
        PHB
        LDA.B #$85
        PHA
        PLB
        REP #$20
        LDA.W $00D4
        BNE setStateFlag
        LDA.W $1E94
        AND.W #$00FF
        CMP.W #$0024
        BCS setStateFlag
        LDA.W $056C
        BIT.W #$1000
        BEQ checkStateCondition
        db $E2,$20,$A9,$00,$EB,$A9,$02,$8D,$CA,$00,$9C,$CB,$00,$22,$4E,$8B
        db $80,$A9,$01,$8D,$42,$21,$C2,$20,$A9,$11,$00,$8D,$70,$12,$22,$2B
        db $BF,$80,$4C,$A6,$EF
; [GameState] Checks game state condition and branches. Entry: 16-bit A/X/Y.
checkStateCondition:
        REP #$20
        LDX.W $1E94
        DEX
        DEX
        LDA.W $1E02
        CMP.W $FEBB,X
        BCC setStateFlag
        SEP #$20
        LDA.B #$00
        XBA
        JSL.L InitAudioController
        LDA.W $1E94
        CMP.B #$16
        BEQ setStateFlag
        CMP.B #$24
        BCS setStateFlag
        LDA.B #$01
        STA.W $2142
; [GameState] Sets game state flag. Entry: 8-bit A, 16-bit X/Y.
setStateFlag:
        PLB
        RTL
; [GameState] Clears game state flags. Entry: 8-bit A, 16-bit X/Y.
clearStateFlags:
        SEP #$20
        LDA.B #$00
        XBA
        LDA.W $00C9
        CMP.B #$05
        BEQ updateProgressCounter
        JSR.W processEnemyAI
        JSR.W initLevelMusic
; [GameState] Updates game progress counter. Entry: 8-bit A, 16-bit X/Y.
updateProgressCounter:
        REP #$20
        LDA.W $00D4
        BEQ checkProgressThreshold
        JMP.W loadLevelPalette
; [GameState] Checks progress threshold condition. Entry: 16-bit A/X/Y.
checkProgressThreshold:
        LDA.W $1E94
        AND.W #$00FF
        DEC A
        DEC A
        TAX
        LDA.W $1E02
        CMP.W $FEBB,X
        BCC transitionToNextLevel
        SEP #$20
        LDA.B #$00
        XBA
        JSL.L InitAudioController
        LDA.W $1E94
        CMP.B #$28
        BCS handleLevelComplete
        LDA.B #$01
        STA.W $2142
; [GameState] Handles level completion logic. Entry: 8-bit A, 16-bit X/Y.
handleLevelComplete:
        REP #$20
        JMP.W loadLevelPalette
; [GameState] Transitions to next level. Entry: 16-bit A/X/Y.
transitionToNextLevel:
        LDA.W $1E02
        BIT.W #$0003
        BEQ resetLevelState
        JMP.W loadLevelPalette
; [GameState] Resets level state variables. Entry: 16-bit A/X/Y.
resetLevelState:
        INC.W $0530
        SEP #$20
        LDA.B #$00
        XBA
        LDX.W $0F22
        LDY.W $1E9B
        LDA.B #$80
        STA.W $0E22,X
        STA.W $0E2A,X
        LDA.B #$D0
        STA.W $0E25,X
        STA.W $0E2D,X
        REP #$20
        LDA.W $1E9F
        STA.B $00
        STZ.B $02
        SEP #$20
; [LevelLoad] Loads level data from ROM. Entry: 8-bit A, 16-bit X/Y.
loadLevelData:
        PHB
        LDA.B #$DF
        PHA
        PLB
        LDA.B ($00),Y
        PLB
        CMP.B #$FF
        BEQ loadLevelPalette
        CMP.B #$FE
        BNE initLevelObjects
        LDA.B #$40
        STA.B $03
        INY
        JMP.W loadLevelData
; [LevelLoad] Initializes level objects and entities. Entry: 8-bit A, 16-bit X/Y.
initLevelObjects:
        XBA
        LDA.B #$00
        REP #$20
        LSR A
        LSR A
