        STA.W $0F22
        INY
        STY.W $1E9B
        LDA.W $1E9D
        CLC
        ADC.W #$0010
        BIT.W #$0100
        BEQ setupLevelGraphics
        CLC
        ADC.W #$0100
        CMP.W #$4000
        BCC setupLevelGraphics
        SEC
        SBC.W #$2000
; [LevelLoad] Sets up level graphics and tiles. Entry: 16-bit A/X/Y.
setupLevelGraphics:
